parameters.jsCode:
const original = $('Normalize Feedback Data').item.json;
const aiItem = $input.item.json;

let raw = aiItem.content || aiItem.text || (aiItem.message && aiItem.message.content) || (aiItem.choices && aiItem.choices[0] && aiItem.choices[0].message && aiItem.choices[0].message.content) || '';

if (Array.isArray(raw)) {
  raw = raw.map(function(p) { return p.text || ''; }).join('\n');
}

let parsed;
try {
  const cleaned = String(raw).trim().replace(/^```json/i, '').replace(/^```/, '').replace(/```$/, '').trim();
  parsed = JSON.parse(cleaned);
} catch (err) {
  parsed = {
    sentiment: 'Neutral',
    urgency: 'Low',
    isFeatureRequest: false,
    featureTitle: '',
    featureSummary: '',
    acceptanceCriteria: [],
    suggestedLabels: ['ai-parse-error'],
    category: 'Other',
    parseError: err.message
  };
}

return [{
  json: Object.assign({}, original, parsed)
}];

